export function immediate<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open, or it was already rolled back
    }
    throw err;
  }
  return result;
}

export type SubmitResult =
  | { kind: 'created'; job: JobRow }
  | { kind: 'replayed'; job: JobRow }
  | { kind: 'conflict' };

export interface Store {
  submit(payload: JobPayload, canonical: string, idempotencyKey: string | undefined): SubmitResult;
  getJob(id: string): JobRow | undefined;
  listJobs(): JobRow[];
  heartbeat(nowMs: number): void;
  clearHeartbeat(): void;
  workerLastSeen(): number | undefined;
  /** Replays interrupted attempts: running jobs go back to queued at progress zero, keeping their attempt number. */
  recoverRunning(nowIso: string): number;
  /** Claims the oldest eligible queued job and starts an attempt on it, or returns undefined. */
  claimNext(nowMs: number, nowIso: string): JobRow | undefined;
  recordProgress(id: string, completed: number, nowIso: string): void;
  completeJob(id: string, output: string, nowIso: string): void;
  /** Ends a simulated transient failure: retry later, or fail the job after the last attempt. */
  failAttempt(id: string, attempt: number, nowMs: number, nowIso: string): void;
  close(): void;
}

export function createStore(db: DatabaseSync): Store {
  const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
  const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
  const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
  const insertJob = db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, created_at, updated_at, idempotency_key, payload)
     VALUES (?, 'queued', ?, ?, ?, ?, ?, ?, ?)`,
  );
  const selectHeartbeat = db.prepare('SELECT last_seen_ms FROM worker_heartbeat WHERE id = 1');
  const upsertHeartbeat = db.prepare(
    `INSERT INTO worker_heartbeat (id, last_seen_ms) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET last_seen_ms = excluded.last_seen_ms`,
  );
  const deleteHeartbeat = db.prepare('DELETE FROM worker_heartbeat');
  const recover = db.prepare(
    `UPDATE jobs SET status = 'queued', completed_steps = 0, retry_at_ms = 0, updated_at = ? WHERE status = 'running'`,
  );
  const selectNext = db.prepare(
    `SELECT * FROM jobs WHERE status = 'queued' AND retry_at_ms <= ? ORDER BY seq ASC LIMIT 1`,
  );
  const markRunning = db.prepare(
    `UPDATE jobs SET status = 'running', attempts = ?, completed_steps = 0, in_attempt = 1,
       output = NULL, error = NULL, retry_at_ms = 0, updated_at = ?
     WHERE id = ? AND status = 'queued'`,
  );
  const progress = db.prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
  const complete = db.prepare(
    `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, in_attempt = 0, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  );
  const failTerminal = db.prepare(
    `UPDATE jobs SET status = 'failed', completed_steps = 0, error = ?, output = NULL, in_attempt = 0, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  );
  const retryLater = db.prepare(
    `UPDATE jobs SET status = 'queued', completed_steps = 0, in_attempt = 0, retry_at_ms = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  );

  return {
    submit(payload, canonical, idempotencyKey) {
      return immediate(db, (): SubmitResult => {
        if (idempotencyKey !== undefined) {
          const existing = selectByKey.get(idempotencyKey) as JobRow | undefined;
          if (existing) {
            return existing.payload === canonical ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
          }
        }
        const id = crypto.randomUUID();
        const now = new Date().toISOString();
        insertJob.run(id, payload.input, payload.steps, payload.failAttempts, now, now, idempotencyKey ?? null, canonical);
        return { kind: 'created', job: selectById.get(id) as JobRow };
      });
    },
    getJob: (id) => selectById.get(id) as JobRow | undefined,
    listJobs: () => selectAll.all() as JobRow[],
    heartbeat(nowMs) {
      upsertHeartbeat.run(nowMs);
    },
    clearHeartbeat() {
      deleteHeartbeat.run();
    },
    workerLastSeen() {
      const row = selectHeartbeat.get() as { last_seen_ms: number } | undefined;
      return row?.last_seen_ms;
    },
    recoverRunning(nowIso) {
      return Number(recover.run(nowIso).changes);
    },
    claimNext(nowMs, nowIso) {
      return immediate(db, (): JobRow | undefined => {
        const job = selectNext.get(nowMs) as JobRow | undefined;
        if (!job) return undefined;
        // A replayed attempt keeps the number it already recorded; a new attempt increments it.
        const attempts = job.in_attempt === 1 ? job.attempts : job.attempts + 1;
        markRunning.run(attempts, nowIso, job.id);
        return selectById.get(job.id) as JobRow;
      });
    },
    recordProgress(id, completed, nowIso) {
      progress.run(completed, nowIso, id);
    },
    completeJob(id, output, nowIso) {
      complete.run(output, nowIso, id);
    },
    failAttempt(id, attempt, nowMs, nowIso) {
      if (attempt >= MAX_ATTEMPTS) failTerminal.run(FAILURE_MESSAGE, nowIso, id);
      else retryLater.run(nowMs + RETRY_DELAY_MS, nowIso, id);
    },
    close() {
      db.close();
    },
  };
}

