import type { JobRow } from './db.ts';

export type { JobStatus } from './jobs.ts';

export const JOB_STATUSES = ['queued', 'running', 'completed', 'failed'] as const;
export type JobStatus = (typeof JOB_STATUSES)[number];

export const DEFAULT_STEPS = 5;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MIN_FAIL_ATTEMPTS = 0;
export const MAX_FAIL_ATTEMPTS = 5;
export const MAX_INPUT_LENGTH = 1000;

/** Duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
/** Total attempts, including the first. */
export const MAX_ATTEMPTS = 3;
export const FAILURE_MESSAGE = 'transient failure';

export const HEARTBEAT_INTERVAL_MS = 500;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3000;
export const WORKER_POLL_MS = 100;

export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

export interface FieldError {
  field: string;
  message: string;
}

/** Validated submission with defaults applied. */
export interface JobPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A job as returned by the API. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'] as const;

/**
 * Validates a parsed request body (already known to be a non-null, non-array object). Returns
 * every detectable field error; the payload is present only when there are none.
 */
export function validatePayload(body: Record<string, unknown>): { payload?: JobPayload; fields: FieldError[] } {
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!(ALLOWED_FIELDS as readonly string[]).includes(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else {
    const value = body.input;
    if (typeof value !== 'string') fields.push({ field: 'input', message: 'must be a string' });
    else if (value.length < 1 || value.length > MAX_INPUT_LENGTH)
      fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
    else if (value.trim() === '') fields.push({ field: 'input', message: 'must not be only whitespace' });
    else input = value;
  }

  const steps = integerField(body, 'steps', DEFAULT_STEPS, MIN_STEPS, MAX_STEPS, fields);
  const failAttempts = integerField(body, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS, fields);

  if (fields.length > 0 || steps === undefined || failAttempts === undefined) return { fields };
  return { payload: { input, steps, failAttempts }, fields };
}

function integerField(
  body: Record<string, unknown>,
  name: string,
  fallback: number,
  min: number,
  max: number,
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

/** Canonical form of a validated payload, used to compare idempotent replays. */
export function canonicalPayload(p: JobPayload): string {
  return JSON.stringify({ input: p.input, steps: p.steps, failAttempts: p.failAttempts });
}

/** Converts a stored row to the exact public representation. */
export function toPublicJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

