import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import type { Socket } from 'node:net';
import { readFileSync } from 'node:fs';
import { openDatabase, createStore } from './db.ts';
import {
  HEARTBEAT_STALE_MS,
  IDEMPOTENCY_KEY_PATTERN,
  canonicalPayload,
  toPublicJob,
  validatePayload,
  type FieldError,
  type JobPayload,
} from './jobs.ts';

/** Request bodies larger than this are rejected; the largest valid body is far smaller. */
const MAX_BODY_BYTES = 64 * 1024;
/** How long open requests may keep the server draining before connections are forced closed. */
const DRAIN_TIMEOUT_MS = 2000;

const db = openDatabase();
const store = createStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error = fields === undefined ? { code, message } : { code, message, fields };
  sendJson(res, status, { error });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`, undefined);
  res.setHeader('allow', allowed.join(', '));
}

function isJsonMediaType(contentType: string | undefined): boolean {
  return contentType?.split(';', 1)[0]?.trim().toLowerCase() === 'application/json';
}

type BodyResult = { tooLarge: true } | { tooLarge: false; text: string };

/** Reads the whole request body. Oversized bodies are drained but not stored. */
function readBody(req: IncomingMessage): Promise<BodyResult> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    });
    req.on('end', () => {
      resolve(size > MAX_BODY_BYTES ? { tooLarge: true } : { tooLarge: false, text: Buffer.concat(chunks).toString('utf8') });
    });
    req.on('error', reject);
  });
}

function parseJsonObject(text: string): Record<string, unknown> | undefined {
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return undefined;
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined;
  return value as Record<string, unknown>;
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const fields: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let idempotencyKey: string | undefined;
  if (keyHeader !== undefined) {
    if (IDEMPOTENCY_KEY_PATTERN.test(keyHeader)) idempotencyKey = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let payload: JobPayload | undefined;
  if (body.tooLarge) {
    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (!isJsonMediaType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    const object = parseJsonObject(body.text);
    if (object === undefined) {
      fields.push({ field: 'body', message: 'must be a JSON object' });
    } else {
      const result = validatePayload(object);
      fields.push(...result.fields);
      payload = result.payload;
    }
  }

  if (fields.length > 0 || payload === undefined) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
    return;
  }

  const result = store.submit(payload, canonicalPayload(payload), idempotencyKey);
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, result.kind === 'created' ? 201 : 200, toPublicJob(result.job));
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

