    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (!isJsonMediaType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    const object = parseJsonObject(body.text);
    if (object === undefined) {
