import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, createStore, type JobRow, type Store } from './db.ts';
import { HEARTBEAT_INTERVAL_MS, STEP_MS, WORKER_POLL_MS } from './jobs.ts';

const db = openDatabase();
const store = createStore(db);
const stop = new AbortController();
let stopping = false;

function requestStop(signal: string): void {
  if (stopping) return;
  stopping = true;
  console.log(`worker stopping (${signal})`);
  // Interrupts any pending wait. Unfinished work stays "running" in the database and is replayed
  // by the next worker start, so a shutdown is never recorded as a failed attempt.
  stop.abort();
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => requestStop(signal));

/** Resolves after `ms`, or early (returning false) once a stop has been requested. */
async function pause(ms: number): Promise<boolean> {
  try {
    await sleep(ms, undefined, { signal: stop.signal });
    return true;
  } catch {
    return false;
  }
}

function beat(): void {
  try {
    store.heartbeat(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/**
 * Runs one attempt of a claimed job. Progress is committed after every step, and no transaction
 * is open during the waits, so the server can read progress and the database stays responsive.
 */
async function runAttempt(store: Store, job: JobRow): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    if (!(await pause(STEP_MS))) return; // stopping: leave the attempt open for replay

    if (step === 1 && attempt <= job.fail_attempts) {
      // Simulated transient failure, recorded before any progress.
      store.failAttempt(job.id, attempt, Date.now(), new Date().toISOString());
      console.log(`job ${job.id} attempt ${attempt} failed (transient)`);
      return;
    }

    if (step === job.steps) {
      store.completeJob(job.id, job.input.toUpperCase(), new Date().toISOString());
      console.log(`job ${job.id} completed`);
    } else {
      store.recordProgress(job.id, step, new Date().toISOString());
    }
  }
}

async function main(): Promise<void> {
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_INTERVAL_MS);
  try {
    // Recovery runs only here, at worker startup: any job still "running" was interrupted.
    const recovered = store.recoverRunning(new Date().toISOString());
    if (recovered > 0) console.log(`recovered ${recovered} interrupted job(s)`);
    console.log('worker started');

    while (!stopping) {
      try {
        const job = store.claimNext(Date.now(), new Date().toISOString());
        if (!job) {
          await pause(WORKER_POLL_MS);
          continue;
        }
        console.log(`job ${job.id} attempt ${job.attempts} started`);
        await runAttempt(store, job);
      } catch (err) {
        if (stopping) break;
        console.error('worker error:', err);
        await pause(WORKER_POLL_MS * 5);
      }
    }
  } finally {
    clearInterval(heartbeat);
    try {
      store.clearHeartbeat();
    } catch (err) {
      console.error('could not clear heartbeat:', err);
    }
    store.close();
    console.log('worker stopped');
  }
}

main().catch((err: unknown) => {
  console.error('worker failed:', err);
  process.exitCode = 1;
});

