}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error = fields === undefined ? { code, message } : { code, message, fields };
  sendJson(res, status, { error }, headers);
}

