const noCt = await fetch(`${base}/api/jobs`, { method: 'POST', headers: { 'content-type': 'text/plain' }, body: '{"input":"a"}' });
check('wrong content type', noCt.status === 400 && (await noCt.json()).error.fields[0].field === 'body');
const ctOk = await fetch(`${base}/api/jobs`, { method: 'POST', headers: { 'content-type': 'Application/JSON; charset=utf-8' }, body: '{"input":"  spaced  ","steps":1}' });
const ctJob = await ctOk.json();
check('charset param accepted; whitespace preserved', ctOk.status === 201 && ctJob.input === '  spaced  ', ctJob);
const badKey = await post({ input: 'a' }, { 'Idempotency-Key': 'bad key!' });
check('bad idempotency key', badKey.status === 400 && badKey.json.error.fields[0].field === 'Idempotency-Key', badKey);

// Routing
check('unknown path 404 json', (await fetch(`${base}/nope`)).status === 404);
const m = await fetch(`${base}/health`, { method: 'POST' });
check('wrong method 405', m.status === 405 && (await m.json()).error.code === 'method_not_allowed');
const missing = await fetch(`${base}/api/jobs/does-not-exist`);
check('missing id 404', missing.status === 404 && (await missing.json()).error.code === 'not_found');
const lst = await (await fetch(`${base}/api/jobs?x=1`)).json();
check('list with query string', Array.isArray(lst.jobs));

// Retries 0..5
const outcomes = {};
for (let f = 0; f <= 5; f++) {
  const r = await post({ input: `retry ${f}`, steps: 2, failAttempts: f });
  const id = r.json.id;
  const j = await waitFor(id, (x) => x.status === 'completed' || x.status === 'failed', 20000);
  outcomes[f] = { status: j.status, attempts: j.attempts, error: j.error, result: j.result };
  const expectOk = f < 3;
  check(`failAttempts=${f}`, expectOk ? (j.status === 'completed' && j.attempts === f + 1 && j.result.output === `RETRY ${f}`) : (j.status === 'failed' && j.attempts === 3 && j.error === 'transient failure' && j.result === null), j);
}

// Progress observed on 20-step job
const big = await post({ input: 'progress', steps: 20 });
const seen = new Set();
for (let i = 0; i < 60; i++) { const j = await get(big.json.id); seen.add(j.progress.completed); if (j.status === 'completed') break; await sleep(60); }
check('intermediate progress observed', [...seen].some((v) => v > 0 && v < 20), [...seen]);

// Unicode uppercase
const uni = await post({ input: 'straße ǆ' , steps: 1 });
const uj = await waitFor(uni.json.id, (x) => x.status === 'completed', 4000);
check('unicode uppercase', uj.result?.output === 'STRASSE Ǆ'.replace('Ǆ', 'Ǆ') || uj.result?.output === 'STRASSE Ǆ', uj);

// Idempotency concurrency + replay + defaults
const key = { 'Idempotency-Key': 'k-concurrent-1' };
const rs = await Promise.all([1, 2, 3, 4].map(() => post({ input: 'idem' }, key)));
const ids = new Set(rs.map((r) => r.json.id));
check('concurrent same key -> one job', ids.size === 1 && rs.filter((r) => r.status === 201).length === 1, rs.map((r) => r.status));
const rep = await post({ input: 'idem', steps: 5, failAttempts: 0 }, key);
check('replay explicit defaults 200', rep.status === 200 && rep.json.id === [...ids][0]);
const conf = await post({ input: 'idem', steps: 6 }, key);
check('different payload 409', conf.status === 409 && conf.json.error.code === 'idempotency_conflict');
const noKey1 = await post({ input: 'idem' }); const noKey2 = await post({ input: 'idem' });
check('no-key submissions create new jobs', noKey1.status === 201 && noKey2.status === 201 && noKey1.json.id !== noKey2.json.id);

// Newest first ordering
const list = (await (await fetch(`${base}/api/jobs`)).json()).jobs;
check('newest first', list[0].id === noKey2.json.id, list[0]);

// Worker kill during processing -> health down, restart -> recovered
const dur = await post({ input: 'survive', steps: 10, failAttempts: 0 });
await waitFor(dur.json.id, (x) => x.status === 'running' && x.progress.completed >= 2, 5000);
procs.worker.kill('SIGKILL'); await exited(procs.worker);
const killedAt = Date.now();
let down = false;
while (Date.now() - killedAt < 6000) { const h = await (await fetch(`${base}/health`)).json(); if (h.worker === 'down') { down = Date.now() - killedAt; break; } await sleep(200); }
check('health down within 3s of kill', down !== false && down <= 3500, down);
const mid = await get(dur.json.id);
check('job left running after SIGKILL', mid.status === 'running', mid);
// Retry-waiting kill: failAttempts 1 gives a retry window
const retryJob = await post({ input: 'rw', steps: 1, failAttempts: 2 });
start('worker');
const restartAt = Date.now();
const after = await waitFor(dur.json.id, (x) => x.status === 'completed', 12000);
check('interrupted job completes after restart within bound', after.status === 'completed' && after.result.output === 'SURVIVE' && Date.now() - restartAt < 12000, after);
check('interrupted attempt not double counted', after.attempts === 1, after);
const rj = await waitFor(retryJob.json.id, (x) => x.status === 'completed' || x.status === 'failed', 12000);
check('retry job after restart', rj.status === 'completed' && rj.attempts === 3, rj);
t0 = Date.now();
check('worker up again', (await (await fetch(`${base}/health`)).json()).worker === 'up');

// Restart server, replay key, check job count persists
procs.server.kill('SIGTERM'); const s1 = await exited(procs.server);
check('server SIGTERM clean exit', s1.code === 0, s1);
start('server');
await sleep(800);
const afterRestart = await post({ input: 'idem' }, key);
check('key survives server restart', afterRestart.status === 200 && afterRestart.json.id === [...ids][0], afterRestart);
const finishedBefore = await get(dur.json.id);
check('terminal jobs persist', finishedBefore.status === 'completed');

// SIGTERM both
const w0 = Date.now();
procs.worker.kill('SIGTERM'); const wExit = await exited(procs.worker);
check('worker SIGTERM clean exit', wExit.code === 0, wExit);
console.log(`worker exit took ${Date.now() - w0} ms`);
procs.server.kill('SIGTERM'); const sExit = await exited(procs.server);
check('server SIGTERM clean exit 2', sExit.code === 0, sExit);
console.log(`PASSED ${results.filter(Boolean).length}/${results.length}`);
process.exit(0);
